import math
import numpy as np
from scipy.optimize import least_squares

_params = None

def _memory(row, tau):
    if row.get('mem_conv') is not None:
        return float(row['mem_conv'])
    prefix = row['raw_prefix']
    end = float(prefix[-1]['t'])
    z = 0.52 * float(prefix[0]['x']) * math.exp(-(end - float(prefix[0]['t'])) / tau)
    for left, right in zip(prefix[:-1], prefix[1:]):
        t0, t1 = float(left['t']), float(right['t'])
        f0 = float(left['x']) * math.exp(-(end - t0) / tau)
        f1 = float(right['x']) * math.exp(-(end - t1) / tau)
        z += 0.52 * (t1 - t0) * (f0 + f1) / (2.0 * tau)
    return z

def _forecast(row, p):
    a, b, c, tau = p
    x = float(row['x_now'])
    z = _memory(row, tau)
    u = float(row['u_now'])
    H = float(row['H'])
    n = max(1, int(math.ceil(abs(H) / 0.004)))
    h = H / n
    def deriv(x, z):
        return -a * x + b * z + c * u, (0.52 * x - z) / tau
    for _ in range(n):
        k1x, k1z = deriv(x, z)
        k2x, k2z = deriv(x + h*k1x/2, z + h*k1z/2)
        k3x, k3z = deriv(x + h*k2x/2, z + h*k2z/2)
        k4x, k4z = deriv(x + h*k3x, z + h*k3z)
        x += h * (k1x + 2*k2x + 2*k3x + k4x) / 6
        z += h * (k1z + 2*k2z + 2*k3z + k4z) / 6
    return float(x)

def fit(train_rows):
    global _params
    rows = list(train_rows)
    def residual(p):
        return np.array([_forecast(row, p) - float(row['y']) for row in rows])
    result = least_squares(residual, [1.0, 0.5, 1.0, 0.5], bounds=([0.0, 0.0, 0.0, 0.02], [10.0, 10.0, 10.0, 10.0]), max_nfev=2000, xtol=1e-11, ftol=1e-11, gtol=1e-11)
    _params = result.x

def predict(row):
    return _forecast(row, _params)
